{
  "name": "奥林巴斯IX81卤素灯",
  "name_en": "Olympus IX81 Halogen Lamp",
  "manufacturer": "Olympus",
  "description": "用于奥林巴斯 IX81 倒置显微镜的卤素照明光源，为样品观察提供可见光照明，常用于明场或透射照明下的常规显微成像与对焦。",
  "description_en": "A halogen illumination source for the Olympus IX81 inverted microscope, providing visible-light illumination for sample observation and commonly used for routine microscopy and focusing in brightfield or transmitted-light imaging.",
  "actions": [
    {
      "action_name": "auto-IsOn",
      "description": "检查卤素灯是否处于开启状态。",
      "description_en": "Check whether the halogen lamp is on."
    },
    {
      "action_name": "auto-TurnOn",
      "description": "打开卤素灯照明。",
      "description_en": "Turn on the halogen lamp illumination."
    },
    {
      "action_name": "auto-TurnOff",
      "description": "关闭卤素灯照明。",
      "description_en": "Turn off the halogen lamp illumination."
    }
  ],
  "tag_hints": [
    "Olympus IX81",
    "halogen lamp",
    "microscope illumination",
    "inverted microscope",
    "transmitted light imaging",
    "brightfield microscopy"
  ]
}

